contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        bool reverted;
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            (reverted || msg.sender != c.DEPOSITOR_ACCOUNT()) ||
            (
                c.number() == _number &&
                c.timestamp() == _timestamp &&
                c.basefee() == _basefee &&
                c.hash() == _hash &&
                c.sequenceNumber() == _sequenceNumber &&
                c.batcherHash() == _batcherHash &&
                c.l1FeeOverhead() == _l1FeeOverhead &&
                c.l1FeeScalar() == _l1FeeScalar
            )
        );
    }
}

